<?php
require 'config/auth.php';require 'config/db.php';require 'config/budget_catalog.php';require_roles(['admin']);
$ready=budget_catalog_ready($conn);$error='';
$labels=['strategy'=>'ยุทธศาสตร์','plan'=>'แผนงาน','activity'=>'กิจกรรม','group'=>'กลุ่มงบงาน','work'=>'งบงานย่อย / โครงการ'];
$parents=['strategy'=>null,'plan'=>'strategy','activity'=>'plan','group'=>'activity','work'=>'group'];
$tab=($_GET['tab']??'catalog')==='assign'?'assign':'catalog';
$kind=array_key_exists($_GET['kind']??'',$labels)?$_GET['kind']:'strategy';
if($_SERVER['REQUEST_METHOD']==='POST')try {
 if(!$ready)throw new DomainException('กรุณาติดตั้งตารางโครงสร้างงบงาน v9 ในชุดพัฒนาก่อน');
 begin_financial_transaction($conn);$action=$_POST['action']??'';
 if($action==='node') {
  budget_catalog_save($conn,$_POST);
  $redirect='budget_catalog.php?kind='.urlencode($_POST['node_kind']).'&parent_id='.(int)($_POST['parent_id']??0);
 } elseif($action==='delete') {
  if(($_POST['confirm_delete']??'')!=='1')throw new DomainException('กรุณายืนยันการลบรายการก่อน');
  $deletedKind=budget_catalog_delete($conn,(int)($_POST['id']??0));$redirect='budget_catalog.php?kind='.urlencode($deletedKind).'&deleted=1';
 } elseif($action==='assign') {
  budget_catalog_assign($conn,$_POST);$redirect='budget_catalog.php?tab=assign&sub_unit_id='.(int)$_POST['sub_unit_id'].'&secondary_unit_id='.(int)$_POST['secondary_unit_id'];
 } elseif($action==='unassign') {
  budget_catalog_unassign($conn,$_POST);$redirect='budget_catalog.php?tab=assign';
 } else throw new DomainException('รายการไม่ถูกต้อง');
 $conn->commit();header('Location: '.$redirect.'&saved=1');exit;
} catch(Throwable $e){$conn->rollback();$error=operation_error($e);}
$nodes=$ready?budget_catalog_nodes($conn):[];$byId=[];foreach($nodes as $n)$byId[(int)$n['id']]=$n;
$edit=$byId[(int)($_GET['edit']??0)]??null;
$delete=$byId[(int)($_GET['delete']??0)]??null;
if($delete)$kind=$delete['node_kind'];
$form=$error&&($_POST['action']??'')==='node'?$_POST:($edit??[]);$kind=array_key_exists($form['node_kind']??'',$labels)?$form['node_kind']:$kind;
$parentId=(int)($form['parent_id']??$_GET['parent_id']??0);
$units=organization_ready($conn)?organization_units($conn):[];$unitsById=[];foreach($units as $u)$unitsById[(int)$u['id']]=$u;
$sub=(int)($_POST['sub_unit_id']??$_GET['sub_unit_id']??0);$secondary=(int)($_POST['secondary_unit_id']??$_GET['secondary_unit_id']??0);
$works=$ready?budget_catalog_works($conn):[];$assignments=$ready?budget_catalog_programs($conn,false):[];
function catalog_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function catalog_path(array $node,array $all):string {
 $parts=[$node['node_name']];$seen=[$node['id']=>true];
 while($node['parent_id']&&isset($all[(int)$node['parent_id']])&&!isset($seen[$node['parent_id']])){$node=$all[(int)$node['parent_id']];$seen[$node['id']]=true;array_unshift($parts,$node['node_name']);}
 return implode(' → ',$parts);
}
?>
