<?php if($ready&&$tab==='catalog'):?><section class="panel"><div class="toolbar"><?php foreach($labels as $k=>$label):?><a class="btn <?=$kind===$k?'btn-primary':'btn-outline'?>" href="?kind=<?=$k?>"><?=$label?></a><?php endforeach;?><a class="btn btn-outline" href="?kind=plan&amp;parent_id=0">+ เพิ่มแผนงานที่ไม่อยู่ภายใต้ยุทธศาสตร์</a></div><h2><?=$edit?'แก้ไข':'เพิ่ม'?><?=catalog_h($labels[$kind])?></h2><?php if($kind==='group'):?><p>เลือกกิจกรรมตามปกติ หรือเลือกแผนงานที่ไม่อยู่ภายใต้ยุทธศาสตร์ได้โดยตรง โดยยุทธศาสตร์และกิจกรรมจะแสดงเป็น -</p><?php endif;?><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="action" value="node"><input type="hidden" name="id" value="<?=(int)($form['id']??0)?>"><input type="hidden" name="node_kind" value="<?=catalog_h($kind)?>"><div class="form-grid form-grid-2">
<?php if($parents[$kind]):?><label><?=$kind==='group'?'กิจกรรม / แผนงานที่ไม่อยู่ภายใต้ยุทธศาสตร์ *':catalog_h($labels[$parents[$kind]]).'ที่สังกัด'.($kind==='plan'?' (ไม่ระบุได้)':' *')?></label><select name="parent_id" <?=$kind==='plan'?'':'required'?>><option value="">เลือก<?=catalog_h($labels[$parents[$kind]])?></option><?php if($kind==='plan'):?><option value="0" <?=$parentId===0?'selected':''?>>ไม่อยู่ภายใต้ยุทธศาสตร์ (-)</option><?php endif;?><?php foreach($nodes as $n):if(!budget_catalog_parent_allowed($kind,$n)||(!$n['active']&&(int)$n['id']!==$parentId))continue;?><option value="<?=(int)$n['id']?>" <?=$parentId===(int)$n['id']?'selected':''?>><?=catalog_h(($kind==='group'&&$n['node_kind']==='plan'?'ไม่อยู่ภายใต้ยุทธศาสตร์ (-) · ':'').catalog_path($n,$byId).' ('.$n['node_code'].')')?></option><?php endforeach;?></select><?php endif;?>
<label>รหัส *</label><input name="node_code" maxlength="50" value="<?=catalog_h($form['node_code']??'')?>" required><label>ชื่อ<?=catalog_h($labels[$kind])?> *</label><input name="node_name" maxlength="255" value="<?=catalog_h($form['node_name']??'')?>" required><label>สถานะ</label><label><input type="checkbox" name="active" value="1" <?=!$form||!empty($form['active'])?'checked':''?>> เปิดใช้งาน</label></div><div class="toolbar"><button class="btn btn-primary">บันทึก</button><?php if($edit):?><a class="btn btn-danger" href="?delete=<?=(int)$edit['id']?>">ลบรายการนี้</a><?php endif;?><a class="btn btn-outline" href="?kind=<?=$kind?>&parent_id=<?=$parentId?>">เพิ่มรายการในสายเดิม</a></div></form></section>
