<?php elseif($ready):?><section class="panel"><h2>เพิ่มงบงานที่หน่วยรองรับผิดชอบ</h2><p>เลือกหน่วยย่อยก่อน แล้วเลือกหน่วยรองและติ๊กงบงานได้หลายรายการ การเพิ่มไม่ลบงานที่เชื่อมไว้ก่อนหน้านี้</p><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="action" value="assign"><div class="form-grid form-grid-2"><label>หน่วยย่อย *</label><select name="sub_unit_id" id="assignment-sub" required><option value="">เลือกหน่วยย่อย</option><?php foreach($units as $u):if($u['unit_level']!=='sub'||!$u['active'])continue;?><option value="<?=(int)$u['id']?>" <?=$sub===(int)$u['id']?'selected':''?>><?=catalog_h($u['unit_name'].' ('.$u['unit_code'].') · '.($unitsById[(int)$u['parent_unit_id']]['unit_name']??''))?></option><?php endforeach;?></select><label>หน่วยรอง *</label><select name="secondary_unit_id" id="assignment-secondary" required><option value="">เลือกหน่วยย่อยก่อน</option><?php foreach($units as $u):if($u['unit_level']!=='secondary'||!$u['active']||(int)$u['parent_unit_id']!==$sub)continue;?><option value="<?=(int)$u['id']?>" <?=$secondary===(int)$u['id']?'selected':''?>><?=catalog_h($u['unit_name'].' ('.$u['unit_code'].')')?></option><?php endforeach;?></select><label>ค้นหางบงาน / แผนงาน</label><input id="assignment-search" type="search" placeholder="พิมพ์ชื่อหรือรหัสเพื่อกรองรายการ"></div><div class="table-wrap"><table><thead><tr><th>เลือก</th><th>งบงานย่อย / โครงการ</th><th>ยุทธศาสตร์ → แผนงาน → กิจกรรม → กลุ่มงบงาน</th></tr></thead><tbody><?php foreach($works as $w):?><tr data-work-row><td><input type="checkbox" name="work_ids[]" value="<?=(int)$w['work_id']?>"></td><td><?=catalog_h($w['work_code'].' · '.$w['work_name'])?></td><td><?=catalog_h(implode(' → ',array_filter([$w['strategy_name'],$w['plan_name'],$w['activity_name'],$w['work_group']])))?></td></tr><?php endforeach;?></tbody></table></div><button class="btn btn-primary">เพิ่มงานที่เลือกให้หน่วยรอง</button></form></section>
